import { useState } from "react";
import { Zap, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator } from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { ThemeToggle } from "@/components/ThemeToggle";
import { CommandMenu } from "@/components/dashboard/CommandMenu";
import { DynamicSidebar } from "@/components/dashboard/DynamicSidebar";
import { WidgetGrid } from "@/components/dashboard/WidgetGrid";
import { useLayout } from "@/lib/layout/LayoutContext";
import { navigationRegistry } from "@/lib/navigation";
import { WIDGET_REGISTRY } from "@/lib/widgetRegistry";

export function MissionControlLayout() {
  const [activeTab, setActiveTab] = useState<string>("dashboard");
  const { currentLayout, setLayoutMode, layouts } = useLayout();
  
  // Mock signals for debug
  const isConnected = true;
  const healthStatus = { status: 'HEALTHY' };

  const activeItem = navigationRegistry.getItem(activeTab);

  return (
    <div className="min-h-screen max-h-screen flex flex-col overflow-hidden bg-[#020205] bg-grid-pattern">
      <CommandMenu setActiveTab={setActiveTab} activeTab={activeTab} />

      <header className="h-16 shrink-0 border-b border-white/5 bg-black/40 backdrop-blur-xl flex items-center justify-between px-6 z-30">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded bg-primary/20 flex items-center justify-center border border-primary/30">
              <Zap size={18} className="text-primary animate-pulse" />
            </div>
            <div className="flex flex-col">
              <span className="text-sm font-bold tracking-tighter text-white uppercase italic">Brunella Cortex</span>
              <span className="text-[10px] font-mono text-primary/60 tracking-widest leading-none">NEURAL NETWORK OS v2.3.0</span>
            </div>
          </div>
          
          <div className="h-4 w-[1px] bg-white/10 mx-2" />
          
          <nav className="flex items-center gap-1">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="text-xs font-mono text-zinc-500 hover:text-zinc-300 transition-colors px-2 py-1 rounded gap-1">
                  LAYOUT: <span className="font-bold text-white">{currentLayout.name.toUpperCase().replace(' ', '_')}</span> <ChevronDown size={14} />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent className="w-56" align="start">
                <DropdownMenuLabel>Válasszon Elrendezést</DropdownMenuLabel>
                <DropdownMenuSeparator />
                {layouts.modes.map((mode) => (
                  <DropdownMenuItem key={mode.id} onClick={() => setLayoutMode(mode.id)} className="cursor-pointer">
                    <span className="font-bold">{mode.name}</span>
                    <span className="ml-auto text-xs text-zinc-500">{mode.id}</span>
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </nav>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
             <div className={cn(
               "w-2 h-2 rounded-full",
               isConnected && healthStatus?.status === 'HEALTHY' ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]" : "bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.8)]"
             )} />
             <span className="text-[10px] font-mono font-bold text-zinc-400">{isConnected ? healthStatus?.status === 'HEALTHY' ? "CORE_ONLINE" : "CORE_DEGRADED" : "CORE_OFFLINE"}</span>
          </div>
          <ThemeToggle />
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden min-h-0">
        <DynamicSidebar activeTab={activeTab} onTabChange={setActiveTab} />

        <main className="flex-1 flex flex-col min-h-0 p-6 relative">
          {activeTab === 'dashboard' ? (
            <div className="flex-1 min-h-0 overflow-y-auto custom-scrollbar">
              <WidgetGrid />
            </div>
          ) : (
            <div className="flex-1 min-h-0 overflow-y-auto custom-scrollbar">
              {activeItem?.component || <div className="text-zinc-500 font-mono">CONTENT_MISSING: {activeTab}</div>}
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Switch } from "@/components/ui/switch";
import {
  Circle,
  CheckCircle,
  Warning,
  XCircle,
  ArrowsClockwise,
} from "@phosphor-icons/react";
import * as api from "@/lib/apiService";
import { toast } from "sonner";

interface ServiceStatus {
  id: string;
  name: string;
  status: "healthy" | "unhealthy" | "checking" | "starting" | "stopping";
  message?: string;
}

export function SystemHealthCard() {
  const [services, setServices] = useState<ServiceStatus[]>([
    { id: "ollama", name: "Ollama", status: "checking" },
    { id: "anythingllm", name: "AnythingLLM", status: "checking" },
    { id: "agents", name: "Agents", status: "checking" },
    { id: "mcp", name: "MCP Servers", status: "checking" },
    { id: "python", name: "Python Service", status: "checking" },
    { id: "cloudflare", name: "Cloudflare", status: "checking" },
  ]);
  const [lastCheck, setLastCheck] = useState<string>("");
  const [isChecking, setIsChecking] = useState(false);
  const [loading, setLoading] = useState<Record<string, boolean>>({});

  const checkHealth = async () => {
    setIsChecking(true);
    try {
      const health = await api.checkHealth();
      const so = (s: { status?: string } | string) =>
        (typeof s === "object" ? s.status : s) ?? "unhealthy";
      const ok = (s: { status?: string } | string) => so(s) === "healthy";

      const newServices: ServiceStatus[] = [
        {
          id: "ollama",
          name: "Ollama",
          status: ok(health.services.ollama) ? "healthy" : "unhealthy",
          message: ok(health.services.ollama)
            ? "Működik"
            : "Indítsd el: ollama serve",
        },
        {
          id: "anythingllm",
          name: "AnythingLLM",
          status: ok(health.services.anythingllm) ? "healthy" : "unhealthy",
          message: ok(health.services.anythingllm)
            ? "Működik"
            : "Service nem elérhető",
        },
        {
          id: "agents",
          name: "Agents",
          status: ok(health.services.agents) ? "healthy" : "unhealthy",
          message: ok(health.services.agents)
            ? "Aktív ágensek rendelkezésre állnak"
            : "Nincs regisztrált ágens",
        },
        {
          id: "mcp",
          name: "MCP Servers",
          status: ok(health.services.mcp) ? "healthy" : "unhealthy",
          message: ok(health.services.mcp)
            ? "MCP kapcsolat működik"
            : "Nincs elérhető MCP szerver",
        },
        {
          id: "python",
          name: "Python Service",
          status: ok(health.services.python) ? "healthy" : "unhealthy",
          message: ok(health.services.python)
            ? "Python alrendszer OK"
            : "Python server nem fut",
        },
        {
          id: "cloudflare",
          name: "Cloudflare",
          status: ok(health.services.cloudflare) ? "healthy" : "unhealthy",
          message: ok(health.services.cloudflare)
            ? "Gateway & R2 OK"
            : "CS csatlakozási hiba",
        },
      ];

      setServices(newServices);
      setLastCheck(new Date().toLocaleString("hu-HU"));
    } catch (error: any) {
      console.error("Health check error:", error);
      setServices((prev) =>
        prev.map((s) => ({
          ...s,
          status: "unhealthy",
          message: "Szerver nem elérhető",
        })),
      );
    } finally {
      setIsChecking(false);
    }
  };

  const handleToggle = async (serviceId: string, currentlyHealthy: boolean) => {
    if (serviceId === "agents" || serviceId === "mcp") {
      toast.info(`${serviceId} állapotát a rendszer automatikusan kezeli`);
      return;
    }

    setLoading((prev) => ({ ...prev, [serviceId]: true }));
    try {
      if (currentlyHealthy) {
        if (serviceId === "anythingllm") {
          toast.info("AnythingLLM Desktop app – manuálisan zárd be");
          return;
        }
        const result = await api.stopService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      } else {
        const result = await api.startService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      }
      await checkHealth();
    } catch (e: any) {
      toast.error(e.message || "Művelet sikertelen");
    } finally {
      setLoading((prev) => ({ ...prev, [serviceId]: false }));
    }
  };

  useEffect(() => {
    checkHealth();
    const interval = setInterval(checkHealth, 30000); // 30s as per masterplan V3
    return () => clearInterval(interval);
  }, []);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "healthy":
        return (
          <CheckCircle size={20} className="text-green-500" weight="fill" />
        );
      case "unhealthy":
        return <XCircle size={14} className="text-red-500" weight="fill" />;
      case "checking":
        return (
          <Circle
            size={14}
            className="text-yellow-500 animate-pulse"
            weight="fill"
          />
        );
      default:
        return <Warning size={14} className="text-gray-500" />;
    }
  };

  const healthyCount = services.filter((s) => s.status === "healthy").length;
  const totalCount = services.length;

  return (
    <Card className="glass-card border-white/10">
      <CardHeader className="flex flex-row items-center justify-between pb-2 border-b border-white/5">
        <CardTitle className="text-sm font-space font-bold tracking-tight uppercase text-muted-foreground flex items-center gap-2">
          <ArrowsClockwise
            size={16}
            className={isChecking ? "animate-spin" : ""}
          />
          System Engine Health
        </CardTitle>
        <div className="flex items-center gap-2">
          <Badge
            variant={healthyCount === totalCount ? "default" : "destructive"}
            className="text-[10px]"
          >
            {healthyCount}/{totalCount} OK
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <div className="divide-y divide-white/5">
          {services.map((service) => {
            const isHealthy = service.status === "healthy";
            const canToggle =
              service.id === "ollama" ||
              service.id === "anythingllm" ||
              service.id === "python";

            return (
              <div
                key={service.id}
                className="flex items-center justify-between p-3 hover:bg-white/5 transition-colors"
              >
                <div className="flex items-center gap-3">
                  {getStatusIcon(service.status)}
                  <div>
                    <p className="font-medium text-xs font-mono">
                      {service.name}
                    </p>
                    <p className="text-[10px] text-muted-foreground truncate max-w-[120px]">
                      {service.message || "System online"}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {canToggle && (
                    <Switch
                      checked={isHealthy}
                      disabled={loading[service.id] || isChecking}
                      onCheckedChange={() =>
                        handleToggle(service.id, isHealthy)
                      }
                      className="scale-75"
                    />
                  )}
                  {!canToggle && (
                    <Badge
                      variant="outline"
                      className="text-[9px] h-5 opacity-50"
                    >
                      AUTO
                    </Badge>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="p-3 bg-muted/20 border-t border-white/5">
          <p className="text-[9px] text-muted-foreground font-mono uppercase text-center">
            Last Check: {lastCheck || "Initializing..."}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { CaretDown, CaretUp, Robot, Lightning, Play, ShareNetwork, PencilSimple, Plus, X } from '@phosphor-icons/react'
import { cn } from '@/lib/utils'
import type { RegistryAgent } from '@/lib/apiService'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import agentCapsHu from '../../data/agentCapabilities_hu.json'

export type AgentStatus = 'idle' | 'working' | 'error'

interface AgentStatusCardProps {
  agent?: RegistryAgent  // Optional to prevent crashes
  status?: AgentStatus
  taskDescription?: string
  onExecute?: (agentName: string, task: string) => void
  allAgents?: RegistryAgent[] // For delegation list
}

export function AgentStatusCard({ agent, status = 'idle', taskDescription, onExecute, allAgents = [] }: AgentStatusCardProps) {
  // Early return if no agent provided
  if (!agent) {
    return (
      <Card className="glass-card border-white/5">
        <CardHeader>
          <CardTitle className="text-sm font-mono text-zinc-400">No Agent Loaded</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-zinc-500">Agent data is not available</p>
        </CardContent>
      </Card>
    )
  }

  const [expanded, setExpanded] = useState(false)
  const [quickTask, setQuickTask] = useState('')
  const [delegateOpen, setDelegateOpen] = useState(false)
  const [selectedDelegate, setSelectedDelegate] = useState<string>('')
  const [delegateTask, setDelegateTask] = useState('')

  // Hungarian data fallback
  const huData = (agentCapsHu as any)[agent.name] || {};
  const displayTitle = huData.title || agent.name;
  const displayRole = huData.description ? "Specializált Ügynök" : (agent.role || 'Agent');
  const displayDescription = huData.description || agent.description;
  const displayCapabilities = huData.capabilities || agent.capabilities || [];

  // Capability Editing State
  const [capabilities, setCapabilities] = useState<string[]>(displayCapabilities)
  const [newCapability, setNewCapability] = useState('')
  const [isEditingCaps, setIsEditingCaps] = useState(false)

  const statusConfig = {
    idle: {
      label: 'Idle',
      color: 'bg-zinc-500',
      pulse: false,
      badge: 'secondary',
    },
    working: {
      label: 'Working',
      color: 'bg-emerald-500',
      pulse: true,
      badge: 'default',
    },
    error: {
      label: 'Error',
      color: 'bg-red-500',
      pulse: false,
      badge: 'destructive',
    },
  }

  const config = statusConfig[status]

  const handleQuickRun = () => {
    if (quickTask.trim() && onExecute) {
      onExecute(agent.name, quickTask.trim())
      setQuickTask('')
    }
  }

  const handleDelegate = async () => {
    if (!selectedDelegate || !delegateTask.trim()) return

    try {
      const response = await fetch(`/api/agents/${agent.name}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          task: `Delegate to ${selectedDelegate}: ${delegateTask}`,
          context: { delegatedTo: selectedDelegate }
        })
      });

      if (!response.ok) throw new Error('Delegation failed')

      toast.success(`Feladat delegálva ${selectedDelegate}-nek!`)
      setDelegateOpen(false)
      setDelegateTask('')
      setSelectedDelegate('')
    } catch (e) {
      toast.error('Delegálás sikertelen')
    }
  }

  const handleAddCapability = async () => {
    if (!newCapability.trim()) return
    const updated = [...capabilities, newCapability.trim()]
    setCapabilities(updated)
    setNewCapability('')
    await saveCapabilities(updated)
  }

  const handleRemoveCapability = async (cap: string) => {
    const updated = capabilities.filter(c => c !== cap)
    setCapabilities(updated)
    await saveCapabilities(updated)
  }

  const saveCapabilities = async (caps: string[]) => {
    try {
      await fetch(`/api/agents/${agent.name}/capabilities`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ capabilities: caps })
      })
      toast.success('Képességek frissítve')
    } catch {
      toast.error('Hiba a mentéskor')
    }
  }

  return (
    <Card
      className={cn(
        'glass-card group h-full flex flex-col',
        status === 'working' ? 'border-primary/30 shadow-[0_0_15px_rgba(139,92,246,0.1)]' : 'border-white/5'
      )}
      onClick={() => setExpanded(!expanded)}
    >
      <CardHeader className="pb-2">
        <CardTitle className="flex items-center justify-between gap-3 text-base font-medium">
          <div className="flex items-center gap-3">
            <span
              className={cn(
                'h-2.5 w-2.5 rounded-full shrink-0',
                config.color,
                config.pulse && 'animate-pulse shadow-[0_0_8px_currentColor]',
              )}
              aria-hidden
            />
            <div className="flex flex-col">
              <span className="font-space font-bold tracking-wide text-zinc-100 group-hover:text-primary transition-colors">{displayTitle}</span>
              <span className="text-[10px] font-mono text-zinc-500 uppercase">{displayRole}</span>
            </div>
          </div>
          <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
            <Dialog open={delegateOpen} onOpenChange={setDelegateOpen}>
              <DialogTrigger asChild>
                <Button variant="ghost" size="icon" className="h-7 w-7 text-zinc-400 hover:text-accent hover:bg-accent/10 rounded-full" title="Delegálás">
                  <ShareNetwork size={16} />
                </Button>
              </DialogTrigger>
              <DialogContent className="glass-panel border-white/10 sm:max-w-[425px]">
                <DialogHeader>
                  <DialogTitle className="text-foreground">Feladat Delegálás</DialogTitle>
                  <DialogDescription>
                    Válassz célügynököt és add meg a feladatot. {displayTitle} fogja továbbítani.
                  </DialogDescription>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                  <div className="grid gap-2">
                    <Label htmlFor="target-agent" className="text-zinc-300">Cél Ügynök</Label>
                    <select
                      id="target-agent"
                      className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-hidden focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 text-zinc-100"
                      value={selectedDelegate}
                      onChange={(e) => setSelectedDelegate(e.target.value)}
                    >
                      <option value="" disabled>Válassz ügynököt...</option>
                      {allAgents.filter(a => a.name !== agent.name).map(a => (
                        <option key={a.name} value={a.name} className="bg-zinc-900">{a.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="grid gap-2">
                    <Label htmlFor="task" className="text-zinc-300">Feladat</Label>
                    <Input
                      id="task"
                      value={delegateTask}
                      onChange={(e) => setDelegateTask(e.target.value)}
                      className="bg-white/5 border-white/10 text-zinc-100"
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button onClick={handleDelegate} className="bg-accent text-accent-foreground hover:bg-accent/90">Küldés</Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            <button
              className="rounded-full p-1 text-zinc-500 hover:bg-white/5 hover:text-zinc-300 transition-colors"
              aria-label={expanded ? 'Összecsuk' : 'Részletek'}
            >
              {expanded ? <CaretUp size={18} /> : <CaretDown size={18} />}
            </button>
          </div>
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-0 space-y-2 flex-1 overflow-auto">
        {(taskDescription || displayDescription) && (
          <p className="text-sm text-zinc-400 line-clamp-2 px-1 font-mono leading-relaxed">{taskDescription || displayDescription}</p>
        )}

        {expanded && (
          <div className="space-y-4 pt-3 border-t border-white/5 mt-2 animate-in slide-in-from-top-2 duration-300" onClick={(e) => e.stopPropagation()}>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1">
                  <Lightning size={10} className="text-yellow-500" />
                  Képességek (Capabilities)
                </span>
                <Popover open={isEditingCaps} onOpenChange={setIsEditingCaps}>
                  <PopoverTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-5 w-5 text-zinc-500 hover:text-zinc-300">
                      <PencilSimple size={12} />
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-80 glass-panel border-white/10 p-3">
                    <div className="space-y-3">
                      <h4 className="font-medium text-sm text-zinc-100">Képességek Szerkesztése</h4>
                      <div className="flex gap-2">
                        <Input
                          value={newCapability}
                          onChange={(e) => setNewCapability(e.target.value)}
                          placeholder="Új képesség..."
                          className="h-8 text-xs bg-white/5 border-white/10"
                        />
                        <Button size="sm" onClick={handleAddCapability} className="h-8 w-8 p-0"><Plus size={14} /></Button>
                      </div>
                      <div className="flex flex-wrap gap-1 max-h-[200px] overflow-y-auto">
                        {capabilities.map(cap => (
                          <Badge key={cap} variant="secondary" className="text-[10px] gap-1 pr-1">
                            {cap}
                            <X
                              size={10}
                              className="cursor-pointer hover:text-red-400"
                              onClick={() => handleRemoveCapability(cap)}
                            />
                          </Badge>
                        ))}
                      </div>
                    </div>
                  </PopoverContent>
                </Popover>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {capabilities?.length > 0 ? (
                  capabilities.map((cap) => (
                    <Badge key={cap} variant="outline" className="text-[10px] font-mono text-cyan-400/90 border-cyan-500/20 bg-cyan-500/5 px-2 py-0.5">
                      {cap}
                    </Badge>
                  ))
                ) : (
                  <span className="text-xs text-zinc-600 italic">No capabilities listed</span>
                )}
              </div>
            </div>

            <div className="flex items-center gap-4 text-xs text-zinc-500 pt-2 border-t border-white/5">
              <span className="flex items-center gap-1.5">
                <div className={`w-1.5 h-1.5 rounded-full ${agent.priority <= 1 ? 'bg-red-500' : 'bg-blue-500'}`} />
                Priority: <span className="text-zinc-300 font-mono">{agent.priority}</span>
              </span>
              {agent.autoStart && (
                <Badge variant="secondary" className="text-[10px] bg-white/10 text-zinc-300 hover:bg-white/20 border-0">
                  Auto-start
                </Badge>
              )}
            </div>

            {onExecute && (
              <div className="flex gap-2 pt-2">
                <div className="relative flex-1">
                  <input
                    type="text"
                    placeholder="Gyors parancs..."
                    className="w-full rounded-md border border-white/10 bg-black/20 px-3 py-1.5 text-xs text-zinc-200 placeholder:text-zinc-600 focus:outline-none focus:border-primary/50 transition-colors font-mono"
                    value={quickTask}
                    onChange={(e) => setQuickTask(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleQuickRun()}
                  />
                  <div className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-zinc-600 font-mono pointer-events-none">
                    ENTER
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="default"
                  className="shrink-0 h-auto py-1 bg-primary hover:bg-primary/90 text-primary-foreground"
                  onClick={handleQuickRun}
                  disabled={!quickTask.trim() || status === 'working'}
                >
                  <Play size={12} weight="fill" />
                </Button>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

