export function AgentStatusMonitor() {
  const { agents } = useSystemSignal();

  // agents is a Map<string, AgentStatusEntry> — Array.from is required, Object.values(Map) returns []
  const agentsList = agents ? Array.from(agents.values()) : [];

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'working': return <Activity size={14} className="text-emerald-500 animate-pulse" />;
      case 'error': return <AlertCircle size={14} className="text-red-500" />;
      default: return <CheckCircle2 size={14} className="text-zinc-500" />;
    }
  };

  return (
    <Card className="glass-card border-white/10 h-full flex flex-col">
      <CardHeader className="pb-2 border-b border-white/5 shrink-0">
        <CardTitle className="text-sm font-space font-bold tracking-tight uppercase text-muted-foreground flex items-center gap-2">
          <Brain size={16} className="text-primary" />
          Agent Status Monitor
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0 flex-1 min-h-0">
        <ScrollArea className="h-full">
          <div className="divide-y divide-white/5">
            {agentsList.length === 0 ? (
              <div className="p-8 text-center text-xs text-zinc-500 font-mono italic">
                NO_AGENTS_DETECTED
              </div>
            ) : agentsList.map((agent) => (
              <div key={agent.name} className="p-3 hover:bg-white/5 transition-colors group">
                <div className="flex items-center justify-between mb-1">
                  <div className="flex items-center gap-2">
                    <span className={cn(
                      "w-1.5 h-1.5 rounded-full",
                      agent.status === 'working' ? "bg-emerald-500 shadow-[0_0_5px_rgba(16,185,129,0.5)]" : 
                      agent.status === 'error' ? "bg-red-500" : "bg-zinc-600"
                    )} />
                    <span className="font-bold text-xs font-mono group-hover:text-primary transition-colors uppercase tracking-tight">
                      {agent.name}
                    </span>
                  </div>
                  <Badge variant={agent.status === 'working' ? 'default' : 'secondary'} className="text-[9px] h-4 px-1 font-mono">
                    {agent.status.toUpperCase()}
                  </Badge>
                </div>
                {agent.taskDescription && (
                  <div className="flex items-start gap-1.5 mt-1 px-3 py-1 bg-white/5 rounded border border-white/5">
                    <Clock size={10} className="text-zinc-500 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 font-mono line-clamp-1 italic leading-tight">
                      {agent.taskDescription}
                    </p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </ScrollArea>
      </CardContent>
      <div className="p-2 bg-black/20 border-t border-white/5 shrink-0">
        <div className="flex justify-between items-center px-2">
          <span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest">Active: {agentsList.filter(a => a.status === 'working').length}</span>
          <span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest">Total: {agentsList.length}</span>
        </div>
      </div>
    </Card>
  );
}

import { useSystemSignalStore } from "../store/systemSignalStore";
import { useShallow } from "zustand/react/shallow";
import { useSocket } from "../context/SocketContext";

export function useSystemSignal() {
  const { socket } = useSocket();
  
  // Return state and actions from the store, or specific derived values
  // useShallow is REQUIRED: without it, the selector returns a new object every render,
  // causing useSyncExternalStore (Zustand v5) to trigger an infinite re-render loop
  // ("Maximum update depth exceeded").
  return {
    ...useSystemSignalStore(useShallow((state) => ({
      isConnected: state.isConnected,
      logs: state.logs,
      agents: state.agents,
      chatter: state.chatter,
      robotkezPlan: state.robotkezPlan,
      robotkezSteps: state.robotkezSteps,
      tasks: state.tasks,
      taskStats: state.taskStats,
      healthStatus: state.healthStatus,
      developerMetrics: state.developerMetrics,
      error: state.error,
      isLoading: state.isLoading,
    }))),
    socket,
  };
}

import { create } from 'zustand';
import { LogEntry, AgentStatusEntry, ChatterEntry, RobotkezPlan, RobotkezStep } from '@/context/SocketContext';
import { QueuedTask, TaskStats, HealthStatus, DeveloperMetricsData } from '@/lib/apiService';

interface SystemSignalState {
  // WebSocket-től származó adatok (a SocketContext-ből refaktorálva)
  isConnected: boolean;
  logs: LogEntry[];
  agents: Map<string, AgentStatusEntry>;
  chatter: ChatterEntry[];
  robotkezPlan: RobotkezPlan | null;
  robotkezSteps: RobotkezStep[];

  // REST API-ból származó adatok (polling, vagy egyszeri lekérés)
  tasks: QueuedTask[];
  taskStats: TaskStats | null;
  healthStatus: HealthStatus | null;
  developerMetrics: DeveloperMetricsData | null;

  // Általános állapotkezelés
  error: string | null;
  isLoading: boolean;
}

interface SystemSignalActions {
  // WebSocket actionök
  setConnected: (isConnected: boolean) => void;
  addLog: (log: Omit<LogEntry, 'id'>) => void;
  addChatter: (chatter: Omit<ChatterEntry, 'id'>) => void;
  updateAgentStatus: (agentName: string, status: AgentStatusEntry['status'], taskDescription?: string) => void;
  setRobotkezPlan: (plan: RobotkezPlan) => void;
  updateRobotkezStep: (step: Partial<RobotkezStep> & { index: number }) => void;
  clearRobotkez: () => void;

  // REST API actionök
  setTasks: (tasks: QueuedTask[]) => void;
  setTaskStats: (stats: TaskStats) => void;
  setHealthStatus: (status: HealthStatus) => void;
  setDeveloperMetrics: (metrics: DeveloperMetricsData) => void;

  // Általános actionök
  setError: (error: string | null) => void;
  setLoading: (isLoading: boolean) => void;
  
  // Clear all data (e.g., on logout or system reset)
  clearAllData: () => void;
}

const MAX_LOGS = 200;
const MAX_CHATTER = 100;
let logIdCounter = 0;
let chatterIdCounter = 0;

export const useSystemSignalStore = create<SystemSignalState & SystemSignalActions>()((set, get) => ({
  // Initial state
  isConnected: false,
  logs: [],
  agents: new Map(),
  chatter: [],
  robotkezPlan: null,
  robotkezSteps: [],
  tasks: [],
  taskStats: null,
  healthStatus: null,
  developerMetrics: null,
  error: null,
  isLoading: false,

  // Actions
  setConnected: (isConnected) => set({ isConnected }),
  addLog: (payload) => set((state) => ({
    logs: [{ ...payload, id: `log-${++logIdCounter}` }, ...state.logs].slice(0, MAX_LOGS),
  })),
  addChatter: (payload) => set((state) => ({
    chatter: [{ ...payload, id: `chat-${++chatterIdCounter}` }, ...state.chatter].slice(0, MAX_CHATTER),
  })),
  updateAgentStatus: (agentName, status, taskDescription) => set((state) => {
    const agents = new Map(state.agents);
    agents.set(agentName, { name: agentName, status, taskDescription, lastUpdated: Date.now() });
    return { agents };
  }),
  setRobotkezPlan: (plan) => set((state) => ({
    robotkezPlan: plan,
    robotkezSteps: plan.plan.plan.map((s, i) => ({ ...s, index: i, status: 'pending' }))
  })),
  updateRobotkezStep: (payload) => set((state) => {
    const steps = [...state.robotkezSteps];
    const idx = payload.index;
    if (steps[idx]) {
      steps[idx] = { ...steps[idx], ...payload };
    }
    return { robotkezSteps: steps };
  }),
  clearRobotkez: () => set({ robotkezPlan: null, robotkezSteps: [] }),

  setTasks: (tasks) => set({ tasks }),
  setTaskStats: (taskStats) => set({ taskStats }),
  setHealthStatus: (healthStatus) => set({ healthStatus }),
  setDeveloperMetrics: (developerMetrics) => set({ developerMetrics }),

  setError: (error) => set({ error }),
  setLoading: (isLoading) => set({ isLoading }),

  clearAllData: () => set({
    isConnected: false,
    logs: [],
    agents: new Map(),
    chatter: [],
    robotkezPlan: null,
    robotkezSteps: [],
    tasks: [],
    taskStats: null,
    healthStatus: null,
    developerMetrics: null,
    error: null,
    isLoading: false,
  }),
}));

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import { io, type Socket } from "socket.io-client";
import { useSystemSignalStore } from "../store/systemSignalStore";
import {
  getTasks,
  getTaskStats,
  checkHealth,
  getDeveloperMetrics,
} from "../lib/apiService";

export type LogType = "info" | "error" | "success";

export interface LogEntry {
  id: string;
  message: string;
  type: LogType;
  timestamp: number;
  source?: string;
}

export type AgentStatusPayload = "idle" | "working" | "error";

export interface RobotkezStep {
  index: number;
  status: 'pending' | 'working' | 'completed' | 'error';
  description: string;
  screenshot?: string;
  error?: string;
}

export interface RobotkezPlan {
  taskId: string;
  plan: {
    plan: RobotkezStep[];
    estimatedDuration: number;
  };
}

export interface AgentStatusEntry {
  name: string;
  status: AgentStatusPayload;
  taskDescription?: string;
  lastUpdated: number;
}

export interface ChatterEntry {
  id: string;
  sender: string;
  receiver?: string;
  message: string;
  context?: any;
  timestamp: number;
}

interface SocketContextValue {
  socket: Socket | null;
}

const SocketContext = createContext<SocketContextValue | null>(null);

const SOCKET_URL = import.meta.env.VITE_SOCKET_URL || "";

export function SocketProvider({ children }: { children: ReactNode }) {
  const [socketInstance, setSocketInstance] = useState<Socket | null>(null);

  // Get actions from the store
  const setConnected = useSystemSignalStore((state) => state.setConnected);
  const addLog = useSystemSignalStore((state) => state.addLog);
  const addChatter = useSystemSignalStore((state) => state.addChatter);
  const updateAgentStatus = useSystemSignalStore((state) => state.updateAgentStatus);
  const setRobotkezPlan = useSystemSignalStore((state) => state.setRobotkezPlan);
  const updateRobotkezStep = useSystemSignalStore((state) => state.updateRobotkezStep);
  const clearRobotkez = useSystemSignalStore((state) => state.clearRobotkez);
  const setError = useSystemSignalStore((state) => state.setError);
  const setLoading = useSystemSignalStore((state) => state.setLoading);
  const setTasks = useSystemSignalStore((state) => state.setTasks);
  const setTaskStats = useSystemSignalStore((state) => state.setTaskStats);
  const setHealthStatus = useSystemSignalStore((state) => state.setHealthStatus);
  const setDeveloperMetrics = useSystemSignalStore((state) => state.setDeveloperMetrics);

  // Initial REST fetch
  useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const [tasksRes, taskStatsRes, healthRes, devMetricsRes] = await Promise.allSettled([
          getTasks(50, 0, "running"),
          getTaskStats(),
          checkHealth(),
          getDeveloperMetrics(),
        ]);

        if (!isMounted) return;

        if (tasksRes.status === "fulfilled") setTasks(tasksRes.value.tasks);
        else setError(tasksRes.reason.message);

        if (taskStatsRes.status === "fulfilled") setTaskStats(taskStatsRes.value);
        else setError(taskStatsRes.reason.message);

        if (healthRes.status === "fulfilled") setHealthStatus(healthRes.value);
        else setError(healthRes.reason.message);

        if (devMetricsRes.status === "fulfilled") setDeveloperMetrics(devMetricsRes.value);
        else setError(devMetricsRes.reason.message);

      } catch (err: any) {
        if (!isMounted) return;
        setError(err.message || "Adatlekérdezési hiba");
        addLog({ message: `REST adatlekérdezési hiba: ${err.message}`, type: "error", source: "SystemSignal" });
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, [setLoading, setError, setTasks, setTaskStats, setHealthStatus, setDeveloperMetrics, addLog]);

  useEffect(() => {
    const socket = io(SOCKET_URL, {
      path: "/socket.io",
      transports: ["polling", "websocket"],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });

    setSocketInstance(socket);

    // Expose socket to window for E2E testing
    if (typeof window !== 'undefined') {
      (window as any).__BRUNELLA_SOCKET__ = socket;
    }

    const getErrorMessage = (error: unknown): string => {
      if (error instanceof Error) return error.message;
      if (typeof error === "string") return error;
      if (typeof error === "object" && error !== null) {
        const maybe = (error as { message?: unknown }).message;
        if (typeof maybe === "string") return maybe;
      }
      return "ismeretlen hiba";
    };

    const log = (message: string, type: LogType = "info") => {
      addLog({
        message,
        type,
        timestamp: Date.now(),
        source: "Socket",
      });
    };

    const onConnect = () => {
      setConnected(true);
      log("Socket csatlakozva ✅", "success");
    };

    const onDisconnect = (reason: unknown) => {
      setConnected(false);
      const r = typeof reason === "string" ? reason : "unknown";
      log(`Socket bontva: ${r}`, "error");
    };

    const onConnectError = (error: unknown) => {
      log(`Socket kapcsolódási hiba: ${getErrorMessage(error)}`, "error");
    };

    const onError = (error: unknown) => {
      const msg = getErrorMessage(error);
      log(`Socket hiba: ${msg}`, "error");
    };

    socket.on("connect", onConnect);
    socket.on("disconnect", onDisconnect);
    socket.on("connect_error", onConnectError);
    socket.on("error", onError);

    // Reconnect UX (manager events)
    const manager = socket.io;
    const onReconnectAttempt = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újrapróbálkozás...${n ? ` (#${n})` : ""}`);
    };
    const onReconnect = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újracsatlakozott ✅${n ? ` (#${n})` : ""}`, "success");
    };
    const onReconnectError = (_err: unknown) => {
      log("Socket újracsatlakozás sikertelen (próbálkozás fut)", "error");
    };
    const onReconnectFailed = () => {
      log("Socket újracsatlakozás feladva (max próbálkozás)", "error");
    };

    manager.on("reconnect_attempt", onReconnectAttempt);
    manager.on("reconnect", onReconnect);
    manager.on("reconnect_error", onReconnectError);
    manager.on("reconnect_failed", onReconnectFailed);

    socket.on(
      "system:log",
      (data: {
        message: string;
        type: LogType;
        timestamp?: number;
        source?: string;
      }) => {
        addLog({
          message: data.message,
          type: data.type ?? "info",
          timestamp: data.timestamp ?? Date.now(),
          source: data.source,
        });
      },
    );

    socket.on(
      "agent:chatter",
      (data: {
        sender: string;
        receiver?: string;
        message: string;
        context?: any;
        timestamp?: number;
      }) => {
        addChatter({
          sender: data.sender,
          receiver: data.receiver,
          message: data.message,
          context: data.context,
          timestamp: data.timestamp ?? Date.now(),
        });
      },
    );

    socket.on(
      "agent:update",
      (data: {
        agentName: string;
        status: AgentStatusPayload;
        taskDescription?: string;
      }) => {
        if (data.agentName && data.status) {
          updateAgentStatus(data.agentName, data.status, data.taskDescription);
        }
      },
    );

    socket.on("robotkez:plan", (data: RobotkezPlan) => {
      setRobotkezPlan(data);
    });

    socket.on("robotkez:step", (data: Partial<RobotkezStep> & { index: number }) => {
      updateRobotkezStep(data);
    });

    socket.on("robotkez:aborted", () => {
      clearRobotkez();
    });

    return () => {
      socket.off("connect", onConnect);
      socket.off("disconnect", onDisconnect);
      socket.off("connect_error", onConnectError);
      socket.off("error", onError);

      manager.off("reconnect_attempt", onReconnectAttempt);
      manager.off("reconnect", onReconnect);
      manager.off("reconnect_error", onReconnectError);
      manager.off("reconnect_failed", onReconnectFailed);

      socket.off("system:log");
      socket.off("agent:update");
      socket.off("agent:chatter");
      socket.off("robotkez:plan");
      socket.off("robotkez:step");
      socket.off("robotkez:aborted");
      socket.disconnect();
      setSocketInstance(null);
    };
  }, [setConnected, addLog, addChatter, updateAgentStatus, setRobotkezPlan, updateRobotkezStep, clearRobotkez]);

  const value: SocketContextValue = {
    socket: socketInstance,
  };

  return (
    <SocketContext.Provider value={value}>{children}</SocketContext.Provider>
  );
}

export function useSocket() {
  const ctx = useContext(SocketContext);
  if (!ctx) throw new Error("useSocket must be used within SocketProvider");
  return ctx;
}

